    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    mov.u32 %r2, %ctaid.x;       // block index (b,oc,od,oh) flattened
    mov.u32 %r3, %tid.x;         // ow in [0,65]
