    mov.u32 %r20, 12582912;
    mul.lo.u32 %r21, %r17, %r20;
    // ocBase = oc * 27
    mov.u32 %r22, 27;
    mul.lo.u32 %r23, %r18, %r22;
    mov.f32 %f1, 0f00000000;
    mov.u32 %r30, 0;   // ic
