    setp.lt.s32 %p3, %r41, 0;
    setp.ge.s32 %p4, %r41, 64;
    or.pred %p5, %p3, %p4;
    @%p5 bra KD_NEXT;
    mov.u32 %r42, 4096;
    mul.lo.u32 %r43, %r41, %r42;
    add.u32 %r44, %r33, %r43;     // inputDBase
    mov.u32 %r45, 9;
    mul.lo.u32 %r46, %r40, %r45;
    add.u32 %r47, %r36, %r46;     // weightDBase
    mov.u32 %r50, 0;   // kh
