    setp.lt.s32 %p12, %r71, 0;
    setp.ge.s32 %p13, %r71, 64;
    or.pred %p14, %p12, %p13;
    mov.f32 %f4, 0f00000000;
    @%p14 bra KW_LOAD_DONE;
    mov.u32 %r72, sharedRow;
    mad.lo.s32 %r73, %r71, 4, %r72;
    ld.shared.f32 %f4, [%r73];
KW_LOAD_DONE:
    add.u32 %r74, %r57, %r70;     // weight elem index
    mul.wide.u32 %rd12, %r74, 4;
    add.s64 %rd13, %rd2, %rd12;
    ld.global.f32 %f5, [%rd13];
    fma.rn.f32 %f1, %f4, %f5, %f1;
    add.u32 %r70, %r70, 1;
    bra KW_LOOP;
KW_DONE:
    bar.sync 0;
KH_NEXT:
    add.u32 %r50, %r50, 1;
    bra KH_LOOP;
KH_DONE:
KD_NEXT:
    add.u32 %r40, %r40, 1;
    bra KD_LOOP;
KD_DONE:
    add.u32 %r30, %r30, 1;
    bra IC_LOOP;
