    // output linear index = blockIdx.x * 66 + ow
    mov.u32 %r80, 66;
    mul.lo.u32 %r81, %r2, %r80;
    add.u32 %r82, %r81, %r3;
    mul.wide.u32 %rd14, %r82, 4;
    add.s64 %rd15, %rd3, %rd14;
    st.global.f32 [%rd15], %f1;
    ret;
